/**
 * 密码强度校验：8-32 位，至少包含两种字符类型（小写、大写、数字、符号）。
 * @returns 校验通过返回 null，否则返回错误文案。
 */
export function validatePasswordStrength(value: string): string | null {
  if (!value) return null
  const len = value.length
  if (len < 8 || len > 32) return '密码长度为 8-32 位'
  const hasLower = /[a-z]/.test(value)
  const hasUpper = /[A-Z]/.test(value)
  const hasNumber = /\d/.test(value)
  const hasSymbol = /[^\w\s]/.test(value)
  const count = [hasLower, hasUpper, hasNumber, hasSymbol].filter(Boolean).length
  if (count < 2) return '密码需包含至少两种：小写字母、大写字母、数字、符号'
  return null
}
